    "flow_key" character varying(320),
    CONSTRAINT ai_agent_operation_pkey PRIMARY KEY ("id")
);

CREATE INDEX idx_ai_agent_operation_space ON public.ai_agent_operation USING btree (space_id, space_code, update_time DESC);

CREATE INDEX idx_ai_agent_operation_status ON public.ai_agent_operation USING btree (status, update_time DESC);

CREATE UNIQUE INDEX uk_ai_agent_operation_flow_key ON public.ai_agent_operation USING btree (creator_id, space_id, space_code, flow_key) WHERE ((del_flag = false) AND (flow_key IS NOT NULL));

