CREATE TABLE "ai_agent_tool_call" (
    "id" character varying(64) NOT NULL,
    "operation_id" character varying(64),
    "tool_name" character varying(128) NOT NULL,
    "user_id" bigint,
    "space_id" bigint,
    "space_code" character varying(128),
    "arguments_json" text,
    "status" character varying(32),
    "result_json" text,
    "duration_ms" bigint,
    "create_time" timestamp without time zone,
    CONSTRAINT ai_agent_tool_call_pkey PRIMARY KEY ("id")
);

CREATE INDEX idx_ai_agent_tool_operation ON public.ai_agent_tool_call USING btree (operation_id, create_time);


CREATE TABLE "ai_ask_message" (
    "id" bigint NOT NULL,
    "session_id" bigint NOT NULL,
    "user_id" bigint NOT NULL,
    "space_id" bigint,
    "role" character varying(32) NOT NULL,
    "content" text,
    "display_content" text,
    "payload_json" text,
    "creator_id" bigint,
    "create_by" character varying(64),
    "create_time" timestamp without time zone,
    "updater_id" bigint,
    "update_by" character varying(64),
    "update_time" timestamp without time zone,
    "remark" character varying(500),
    "del_flag" boolean DEFAULT false,
    CONSTRAINT ai_ask_message_pkey PRIMARY KEY ("id")
);

CREATE INDEX idx_ai_ask_message_session ON public.ai_ask_message USING btree (session_id, id);

