product_name,\n  p.category,\n  p.status AS product_status,\n  COALESCE(SUM(o.quantity), 0) AS total_ordered_qty,\n  COALESCE(SUM(o.amount), 0) AS total_ordered_amount,\n  COALESCE(COUNT(DISTINCT o.order_no), 0) AS order_count,\n  COALESCE(COUNT(DISTINCT pr.work_no), 0) AS production_work_count,\n  COALESCE(SUM(pr.quantity), 0) AS total_production_qty\nFROM dm_product p\nLEFT JOIN dm_order o ON p.product_code = o.product_code\nLEFT JOIN dm_production pr ON p.product_code = pr.product_code\nGROUP BY p.product_code, p.name, p.category, p.status\nORDER BY total_ordered_amount DESC;","sqlUnavailable":false,"steps":[{"key":"understand","label":"理解问题","status":"done"},{"key":"connect","label":"连接数据源","status":"done"},{"key":"answer","label":"生成决策建议","status":"done"}]}', 1, '超级管理员', '2026-09-14T10:24:02.172000'::timestamp, 1, '超级管理员', '2026-09-14T10:24:02.172000'::timestamp, NULL, false);
