    "space_id" bigint,
    "space_code" character varying(128),
    "title" character varying(255) NOT NULL,
    "mode" character varying(32) DEFAULT 'qa'::character varying,
    "datasource_id" bigint,
    "datasource_name" character varying(255),
    "skill_id" bigint,
    "template_id" bigint,
    "return_sql" boolean DEFAULT false,
    "message_count" integer DEFAULT 0,
    "creator_id" bigint,
    "create_by" character varying(64),
    "create_time" timestamp without time zone,
    "updater_id" bigint,
    "update_by" character varying(64),
    "update_time" timestamp without time zone,
    "remark" character varying(500),
    "del_flag" boolean DEFAULT false,
    "category" character varying(32) DEFAULT 'ASK_DATA'::character varying,
