ALTER TABLE "ai_decision_dispatch" ADD CONSTRAINT "uk_ai_decision_dispatch_key" UNIQUE (idempotency_key);

ALTER TABLE "ai_decision_dispatch" ADD CONSTRAINT "uk_ai_decision_dispatch_once" UNIQUE (decision_id);

