CREATE INDEX idx_ai_invocation_operation ON public.ai_model_invocation USING btree (operation_id, created_at DESC);

CREATE INDEX idx_ai_invocation_provider ON public.ai_model_invocation USING btree (space_id, provider, model, created_at DESC);

CREATE INDEX idx_ai_invocation_space_time ON public.ai_model_invocation USING btree (space_id, space_code, created_at DESC);

ALTER TABLE "ai_model_invocation" ADD CONSTRAINT "ai_model_invocation_duration_ms_check" CHECK ((duration_ms >= 0));

ALTER TABLE "ai_model_invocation" ADD CONSTRAINT "ai_model_invocation_input_tokens_check" CHECK ((input_tokens >= 0));

ALTER TABLE "ai_model_invocation" ADD CONSTRAINT "ai_model_invocation_kind_check" CHECK (((kind)::text = ANY ((ARRAY['MODEL'::character varying, 'DBGPT'::character varying])::text[])));

ALTER TABLE "ai_model_invocation" ADD CONSTRAINT "ai_model_invocation_output_tokens_check" CHECK ((output_tokens >= 0));

ALTER TABLE "ai_model_invocation" ADD CONSTRAINT "ai_model_invocation_status_check" CHECK (((status)::text = ANY ((ARRAY['SUCCESS'::character varying, 'FAILURE'::character varying, 'REJECTED'::character varying])::text[])));

ALTER TABLE "ai_model_invocation" ADD CONSTRAINT "ai_model_invocation_total_tokens_check" CHECK ((total_tokens >= 0));

COMMENT ON TABLE "ai_model_invocation" IS '平台逻辑调用统计；含内部重试，一次begin一条记录。DB-GPT不代表内部模型次数；usage未知为NULL，不以0替代';

CREATE TABLE "ai_model_profile" (
    "id" bigint NOT NULL,
    "space_id" bigint NOT NULL,
    "space_code" character varying(128) NOT NULL,
    "name" character varying(100) NOT NULL,
    "provider" character varying(64) NOT NULL,
    "model" character varying(100) NOT NULL,
    "api_url" character varying(500) NOT NULL,
    "enabled" boolean DEFAULT true NOT NULL,
    "active" boolean DEFAULT false NOT NULL,
    "api_key_ciphertext" text NOT NULL,
    "created_at" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ai_model_profile_pkey PRIMARY KEY ("id")
);

CREATE SEQUENCE IF NOT EXISTS "ai_model_profile_id_seq";
ALTER SEQUENCE "ai_model_profile_id_seq" OWNED BY "ai_model_profile"."id";
ALTER TABLE "ai_model_profile" ALTER COLUMN "id" SET DEFAULT nextval('ai_model_profile_id_seq'::regclass);
SELECT setval('ai_model_profile_id_seq', 1, FALSE);

CREATE INDEX idx_ai_model_profile_space_enabled ON public.ai_model_profile USING btree (space_id, enabled);

CREATE UNIQUE INDEX uk_ai_model_profile_space_active ON public.ai_model_profile USING btree (space_id) WHERE (active = true);

ALTER TABLE "ai_model_profile" ADD CONSTRAINT "ck_ai_model_profile_active_enabled" CHECK (((NOT active) OR enabled));

ALTER TABLE "ai_model_profile" ADD CONSTRAINT "ck_ai_model_profile_ciphertext" CHECK ((api_key_ciphertext ~~ 'gcm1:%'::text));

ALTER TABLE "ai_model_profile" ADD CONSTRAINT "ck_ai_model_profile_provider" CHECK (((provider)::text ~ '^[A-Z][A-Z0-9_]{0,63}$'::text));

ALTER TABLE "ai_model_profile" ADD CONSTRAINT "uk_ai_model_profile_space_name" UNIQUE (space_id, name);

COMMENT ON TABLE "ai_model_profile" IS 'Per-space OpenAI-compatible MODEL profiles; encrypted credentials never exposed through management/member responses';
COMMENT ON COLUMN "ai_model_profile"."provider" IS 'Provider label such as BAILIAN, OPENAI_COMPATIBLE, DEEPSEEK, OTHER; not a protocol adapter';
COMMENT ON COLUMN "ai_model_profile"."active" IS 'At most one active/default profile per space; new profiles start inactive';
COMMENT ON COLUMN "ai_model_profile"."api_key_ciphertext" IS 'Versioned AES-GCM ciphertext with per-space authenticated data; never store plaintext';

CREATE TABLE "ai_model_routing" (
    "space_id" bigint NOT NULL,
    "space_code" character varying(128) NOT NULL,
    "enabled" boolean DEFAULT false NOT NULL,
    "economy_profile_id" bigint,
    "advanced_profile_id" bigint,
