    "revision" integer DEFAULT 1 NOT NULL,
    "updated_by" bigint NOT NULL,
    "updated_at" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ai_model_routing_pkey PRIMARY KEY ("space_id")
);

ALTER TABLE "ai_model_routing" ADD CONSTRAINT "ai_model_routing_check" CHECK (((NOT enabled) OR ((economy_profile_id IS NOT NULL) AND (advanced_profile_id IS NOT NULL))));

ALTER TABLE "ai_model_routing" ADD CONSTRAINT "ai_model_routing_complex_input_characters_check" CHECK (((complex_input_characters >= 1) AND (complex_input_characters <= 16000)));

ALTER TABLE "ai_model_routing" ADD CONSTRAINT "ai_model_routing_revision_check" CHECK ((revision > 0));

COMMENT ON TABLE "ai_model_routing" IS 'Per-space model routing override; absent row uses deployment defaults, disabled row explicitly disables routing';

