  - 商品编码 (propertyId=2098347836760002563, code=product_code, type=string, primary=false, required=false)
  - 商品名称 (propertyId=2098347836822917122, code=product_name, type=string, primary=false, required=false)
  - 分类 (propertyId=2098347836822917123, code=category, type=string, primary=false, required=true)
