CREATE TABLE "cat_task" (
    "id" bigint NOT NULL,
    "source_system_id" bigint,
    "source_system_name" character varying,
    "name" character varying NOT NULL,
    "datasource_id" bigint NOT NULL,
    "db_type" character varying NOT NULL,
    "leader" bigint,
    "leader_phone" character varying,
    "collection_mode" character varying DEFAULT '1'::character varying NOT NULL,
    "collection_scope" character varying DEFAULT '1'::character varying NOT NULL,
    "status" character varying DEFAULT '0'::character varying NOT NULL,
    "valid_flag" character varying DEFAULT '1'::character varying NOT NULL,
    "del_flag" character varying DEFAULT '0'::character varying NOT NULL,
    "create_by" character varying,
    "creator_id" bigint,
    "create_time" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "update_by" character varying,
    "updater_id" bigint,
    "update_time" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "remark" character varying,
    "description" character varying,
    "collect_type" smallint DEFAULT '1'::smallint NOT NULL,
    "blacklist" text,
    "responsible_dept" bigint,
    "space_code" character varying,
    "space_id" bigint
);

COMMENT ON TABLE "cat_task" IS 'cat_task';
COMMENT ON COLUMN "cat_task"."space_code" IS '项目编码';
COMMENT ON COLUMN "cat_task"."space_id" IS '项目ID';


CREATE TABLE "cat_task_instance" (
    "id" bigint NOT NULL,
    "source_system_id" bigint,
    "source_system_name" character varying,
    "task_id" bigint NOT NULL,
    "collection_mode" character varying DEFAULT '1'::character varying NOT NULL,
    "collection_scope" character varying DEFAULT '1'::character varying NOT NULL,
    "total_count" integer DEFAULT 0 NOT NULL,
    "success_count" integer DEFAULT 0,
    "fail_count" integer DEFAULT 0,
    "fail_cause" character varying,
    "add_count" integer DEFAULT 0,
    "del_count" integer DEFAULT 0,
    "update_count" integer DEFAULT 0,
    "start_time" timestamp without time zone NOT NULL,
    "end_time" timestamp without time zone,
    "duration" integer DEFAULT 0,
    "status" character varying DEFAULT '1'::character varying NOT NULL,
    "valid_flag" character varying DEFAULT '1'::character varying NOT NULL,
    "del_flag" character varying NOT NULL,
    "create_by" character varying,
    "creator_id" bigint,
    "create_time" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "update_by" character varying,
    "updater_id" bigint,
    "update_time" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "remark" character varying,
    "description" character varying,
    "space_id" bigint,
    "space_code" character varying
);

COMMENT ON TABLE "cat_task_instance" IS 'cat_task_instance';
COMMENT ON COLUMN "cat_task_instance"."space_id" IS '项目ID';
COMMENT ON COLUMN "cat_task_instance"."space_code" IS '项目编码';


CREATE TABLE "cat_task_instance_log" (
    "task_instance_id" bigint NOT NULL,
    "time" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "task_id" bigint NOT NULL,
    "log_content" text NOT NULL,
    "valid_flag" character varying DEFAULT '1'::character varying NOT NULL,
    "del_flag" character varying DEFAULT '0'::character varying NOT NULL,
    "create_by" character varying,
    "creator_id" bigint,
    "create_time" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "update_by" character varying,
    "updater_id" bigint,
    "update_time" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "remark" character varying,
    "space_id" bigint,
    "space_code" character varying
);

COMMENT ON TABLE "cat_task_instance_log" IS 'cat_task_instance_log';
COMMENT ON COLUMN "cat_task_instance_log"."space_id" IS '项目ID';
COMMENT ON COLUMN "cat_task_instance_log"."space_code" IS '项目编码';

