CREATE TABLE "col_etl_task_ops_policy" (
    "id" bigint NOT NULL,
    "task_id" bigint NOT NULL,
    "task_type" character varying(32),
    "fail_stop_enabled" boolean DEFAULT false,
    "ai_managed" boolean DEFAULT false,
    "auto_recover_enabled" boolean DEFAULT false,
    "max_recover_times" integer DEFAULT 1,
    "recover_strategy" character varying(64) DEFAULT 'SAFE_AUTO'::character varying,
    "notify_users" character varying(500),
    "valid_flag" boolean DEFAULT true,
    "del_flag" boolean DEFAULT false,
    "creator_id" bigint,
    "create_by" character varying(64),
    "create_time" timestamp without time zone,
    "updater_id" bigint,
    "update_by" character varying(64),
    "update_time" timestamp without time zone,
    "remark" character varying(500),
    CONSTRAINT col_etl_task_ops_policy_pkey PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX idx_col_etl_task_ops_policy_task ON public.col_etl_task_ops_policy USING btree (task_id);


CREATE TABLE "col_evaluate_log" (
    "id" bigint NOT NULL,
    "table_name" character varying(128),
    "column_name" character varying(128),
    "rule_code" character varying(32),
    "rule_name" character varying(128),
    "dimension_type" character(1),
    "rule_description" character varying(512),
    "task_log_id" character varying(255) NOT NULL,
    "evaluate_id" character varying(255) NOT NULL,
    "total" bigint DEFAULT 0,
    "problem_total" bigint DEFAULT 0,
    "check_date" timestamp without time zone,
    "valid_flag" character varying(1) DEFAULT '1'::character varying NOT NULL,
    "del_flag" character varying(1) DEFAULT '0'::character varying NOT NULL,
    "create_by" character varying(32),
    "creator_id" bigint,
    "create_time" timestamp without time zone,
    "update_by" character varying(32),
    "updater_id" bigint,
    "update_time" timestamp without time zone,
    "remark" character varying(512),
    "rule" text,
    CONSTRAINT col_evaluate_log_pkey PRIMARY KEY ("id")
);

COMMENT ON TABLE "col_evaluate_log" IS 'col_evaluate_log';


CREATE TABLE "col_lineage_outbox" (
    "id" bigint NOT NULL,
    "task_id" bigint NOT NULL,
    "sequence" bigint NOT NULL,
    "event_type" character varying(20) NOT NULL,
    "version" character varying(128),
    "payload" text NOT NULL,
    "status" character varying(20) DEFAULT 'PENDING'::character varying NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "next_attempt_at" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "lease_until" timestamp without time zone,
    "lease_token" character varying(64),
    "error_code" character varying(80),
    "create_time" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT col_lineage_outbox_pkey PRIMARY KEY ("id")
);

CREATE INDEX idx_col_lineage_outbox_due ON public.col_lineage_outbox USING btree (status, next_attempt_at);

CREATE INDEX idx_col_lineage_outbox_task ON public.col_lineage_outbox USING btree (task_id, sequence DESC);

ALTER TABLE "col_lineage_outbox" ADD CONSTRAINT "col_lineage_outbox_sequence_key" UNIQUE (sequence);

COMMENT ON COLUMN "col_lineage_outbox"."payload" IS 'Minimal published lineage snapshot; may contain SQL expressions but never connection credentials; not a public query API';

