    "create_pk_data_flag" character varying DEFAULT '1'::character varying,
    "valid_flag" character varying DEFAULT '1'::character varying NOT NULL,
    "del_flag" character varying DEFAULT '0'::character varying NOT NULL,
    "create_by" character varying,
    "creator_id" bigint,
    "create_time" timestamp without time zone,
    "update_by" character varying,
    "updater_id" bigint,
    "update_time" timestamp without time zone,
    "remark" character varying,
    "status" character(1) DEFAULT NULL::bpchar,
    "effective_end_time" timestamp without time zone,
