CREATE TABLE "ont_action" (
    "id" bigint NOT NULL,
    "ontology_id" bigint NOT NULL,
    "name" character varying(100) NOT NULL,
    "action_type" character varying(20) NOT NULL,
    "concept_id" bigint,
    "description" text,
    "creator_id" bigint,
    "create_by" character varying(50),
    "create_time" timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    "updater_id" bigint,
    "update_by" character varying(50),
    "update_time" timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    "del_flag" smallint DEFAULT 0,
    "param_config" text,
    "function_id" bigint,
    "source_concept_id" bigint,
    "source_relation_ids" text,
    "output_concept_id" bigint,
    "read_limit" integer DEFAULT 5000,
    "needs_approval" boolean DEFAULT false,
    "submission_criteria" jsonb,
    "approval_levels" integer DEFAULT 1,
    "trigger_ref" character varying(200),
    "approval_reviewers" jsonb,
    "version" integer DEFAULT 1,
    "execution_steps" jsonb,
    CONSTRAINT ont_action_pkey PRIMARY KEY ("id")
);

CREATE INDEX idx_ont_act_oid ON public.ont_action USING btree (ontology_id);

COMMENT ON TABLE "ont_action" IS '动作定义';
COMMENT ON COLUMN "ont_action"."action_type" IS 'CREATE/UPDATE/DELETE/QUERY/FUNCTION';
COMMENT ON COLUMN "ont_action"."concept_id" IS '绑定概念ID（FUNCTION 类型动作可空）';
COMMENT ON COLUMN "ont_action"."param_config" IS '执行参数配置JSON数组:[{"propertyCode":"phone","valueMode":"direct|placeholder|expression","valueTemplate":"${newPhone}","required":true}]';
COMMENT ON COLUMN "ont_action"."function_id" IS '绑定共享函数ID（动作类型=FUNCTION 时必填）';
COMMENT ON COLUMN "ont_action"."source_concept_id" IS '动作绑定函数的读取来源主概念ID（可空：绑定后执行时按属性查询该概念物理表数据注入 input.source.rows）';
COMMENT ON COLUMN "ont_action"."source_relation_ids" IS '可选关联关系ID JSON数组，如 [1,2]（可空：按关系关联表查询数据注入 input.source.relations）';
COMMENT ON COLUMN "ont_action"."output_concept_id" IS '输出目标概念ID（可空：脚本输出 JSON 数组按主键 UPSERT 到该概念物理表，不绑定则仅记录输出 JSON）';
COMMENT ON COLUMN "ont_action"."read_limit" IS '主概念/关系数据读取行数上限（默认 5000，防大批量读取拖垮执行）';
COMMENT ON COLUMN "ont_action"."needs_approval" IS '是否需要在动作绑定函数执行前审批';
COMMENT ON COLUMN "ont_action"."submission_criteria" IS '提交时判定条件表达式 JSONB（不带 = 免判定；带则提交时对对象状态+参数求值）';
COMMENT ON COLUMN "ont_action"."approval_levels" IS '多级审批关卡数，1=单级，>1=多级（每级一名或多位审阅人）';
COMMENT ON COLUMN "ont_action"."trigger_ref" IS '历史触发标识兼容字段；新动作不绑定触发方式，触发来源记录在每次执行的 TRIGGER_TYPE/TRIGGER_REF 中';
COMMENT ON COLUMN "ont_action"."approval_reviewers" IS '多级审批每级审批人配置 JSONB: [{"stage":1,"userId":1001,"userName":"xxx"},...]；空=不绑定审批人(任意用户可审)';
COMMENT ON COLUMN "ont_action"."version" IS '动作定义版本号：提交执行时冻结到执行记录，执行前复核防定义变更后误执行';
COMMENT ON COLUMN "ont_action"."execution_steps" IS '多目标动作有序步骤 JSON 数组：[{stepNo,name,actionType,conceptId,paramConfig}]；同一动作内步骤必须属于同一数据源并在一个事务中执行';

