CREATE TABLE "ont_action_execution" (
    "id" bigint NOT NULL,
    "action_id" bigint NOT NULL,
    "ontology_id" bigint NOT NULL,
    "executor_id" bigint,
    "input_params" jsonb,
    "generated_sql" text,
    "preview_result" jsonb,
    "before_data" jsonb,
    "status" character varying(20) DEFAULT 'DRAFT'::character varying,
    "approval_reason" text,
    "approver_id" bigint,
    "approve_time" timestamp without time zone,
    "execute_time" timestamp without time zone,
    "error_message" text,
    "creator_id" bigint,
    "create_by" character varying(50),
    "create_time" timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    "updater_id" bigint,
    "update_by" character varying(50),
    "update_time" timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    "del_flag" smallint DEFAULT 0,
    "space_id" bigint,
    "space_code" character varying(50),
    "after_data" jsonb,
    "rollback_sql" text,
    "rollback_time" timestamp without time zone,
    "rollback_before_data" jsonb,
    "rollback_after_data" jsonb,
    "object_key" character varying(500),
    "criteria_result" jsonb,
    "current_stage" integer DEFAULT 0,
    "target_table" character varying(255),
    "action_version" integer,
    "function_version" integer,
    "function_hash" character varying(64),
    "idempotency_key" character varying(350),
    "attempt_no" integer DEFAULT 0,
    "lock_time" timestamp without time zone,
    "result_context" jsonb,
    "error_code" character varying(50),
    "workflow_run_id" bigint,
    "workflow_step_id" bigint,
    "parent_execution_id" bigint,
    "lock_owner" character varying(200),
    "auto_execute" boolean DEFAULT false,
    "trigger_type" character varying(30) DEFAULT 'MANUAL'::character varying,
    "trigger_ref" character varying(200),
    "event_id" character varying(300),
    "max_attempts" integer DEFAULT 1,
    "next_run_time" timestamp without time zone,
    CONSTRAINT ont_action_execution_pkey PRIMARY KEY ("id")
);

CREATE INDEX idx_ont_action_execution_workflow_run ON public.ont_action_execution USING btree (workflow_run_id, workflow_step_id);

CREATE INDEX idx_ont_aexec_aid ON public.ont_action_execution USING btree (action_id);

CREATE INDEX idx_ont_aexec_auto_queue ON public.ont_action_execution USING btree (status, next_run_time, id) WHERE ((auto_execute = true) AND ((status)::text = 'APPROVED'::text));

CREATE INDEX idx_ont_aexec_stale_running ON public.ont_action_execution USING btree (lock_time, id) WHERE (((status)::text = 'RUNNING'::text) AND (lock_time IS NOT NULL));

CREATE INDEX idx_ont_aexec_status ON public.ont_action_execution USING btree (status);

CREATE UNIQUE INDEX uk_ont_aexec_idem ON public.ont_action_execution USING btree (action_id, idempotency_key) WHERE (idempotency_key IS NOT NULL);

COMMENT ON TABLE "ont_action_execution" IS '动作执行记录';
COMMENT ON COLUMN "ont_action_execution"."status" IS 'DRAFT/PENDING_APPROVAL/APPROVED/REJECTED/EXECUTED/FAILED';
COMMENT ON COLUMN "ont_action_execution"."space_id" IS '提交时的空间ID（执行阶段二次权限校验用）';
COMMENT ON COLUMN "ont_action_execution"."space_code" IS '提交时的空间编码（执行阶段二次权限校验用）';
COMMENT ON COLUMN "ont_action_execution"."after_data" IS '执行后数据快照（JSONB）：UPDATE=重查新值 / DELETE=空集 / CREATE=按主键回查新行';
COMMENT ON COLUMN "ont_action_execution"."object_key" IS '目标对象主键（对象实例级决策载体；空=批处理未膨胀成逐对象）';
COMMENT ON COLUMN "ont_action_execution"."criteria_result" IS '①提交判定结果 JSONB {passed:boolean, decision:PASS/REJECT/NEED_APPROVAL, detail:[...]}';
COMMENT ON COLUMN "ont_action_execution"."current_stage" IS '多级审批当前关卡（0=未提交审批，>=1 表示已推进到的关卡）';
COMMENT ON COLUMN "ont_action_execution"."action_version" IS '提交时冻结的动作定义版本（执行前复核：定义变更后需重新提交）';
COMMENT ON COLUMN "ont_action_execution"."function_version" IS '提交时冻结的函数版本（函数类型动作）';
COMMENT ON COLUMN "ont_action_execution"."function_hash" IS '提交时冻结的解析函数体 SHA-256（执行前按当前解析体哈希复核一致性）';
COMMENT ON COLUMN "ont_action_execution"."idempotency_key" IS '幂等键：同动作下唯一，重复提交直接返回首次执行记录';
COMMENT ON COLUMN "ont_action_execution"."attempt_no" IS '尝试次数：初始0，每次实际执行前置+1（CAS 抢占并发锁时递增）';
COMMENT ON COLUMN "ont_action_execution"."lock_time" IS '执行中锁标记：非空=正在执行；执行结束清空。仅 APPROVED 且 LOCK_TIME 为空可抢占';
COMMENT ON COLUMN "ont_action_execution"."result_context" IS '统一执行结果上下文 JSONB {actionType,status,objectKey,actionVersion,targetTable,affectedRows,output,...}，作为 Workflow 后续节点的标准输入';
COMMENT ON COLUMN "ont_action_execution"."error_code" IS '失败分类错误码（EXECUTE_ERROR/FUNCTION_ERROR/TRIGGER_SUBMIT_ERROR/STALE_EXECUTION_LOCK/版本或条件错误）';
COMMENT ON COLUMN "ont_action_execution"."workflow_run_id" IS '所属工作流运行ID（阶段二引入，预留）';
COMMENT ON COLUMN "ont_action_execution"."workflow_step_id" IS '所属工作流步骤ID（阶段二引入，预留）';
COMMENT ON COLUMN "ont_action_execution"."parent_execution_id" IS '触发本次执行的上游执行记录ID（动作链衔接，预留）';
COMMENT ON COLUMN "ont_action_execution"."lock_owner" IS '执行锁持有者（实例/进程标识），用于故障定位和对账';
COMMENT ON COLUMN "ont_action_execution"."auto_execute" IS '是否由后台 Worker 自动执行；人工预览确认保持 false';
COMMENT ON COLUMN "ont_action_execution"."trigger_type" IS '触发类型：MANUAL/DATA_ARRIVAL/API/WORKFLOW';
COMMENT ON COLUMN "ont_action_execution"."trigger_ref" IS '触发器引用（如 Kafka topic 或业务事件类型）';
COMMENT ON COLUMN "ont_action_execution"."event_id" IS '来源事件唯一编号；数据到达场景为 topic:partition:offset';
COMMENT ON COLUMN "ont_action_execution"."max_attempts" IS '最大执行尝试次数；V1 写动作默认1，不自动重放';
COMMENT ON COLUMN "ont_action_execution"."next_run_time" IS '最早可执行时间；用于延迟执行和后续重试扩展';


# ===== 人物概念：属性 code 即行键 =====
#   标识 = prop_mte737eq6byt （映射物理列 id）
#   年龄 = 11               （映射物理列 age）
# input.source.rows = [ {"prop_mte737eq6byt":1,"11":30}, ... ]
#
# 【参数引用】
#   - ''1''：编译期直接内联替换
#   - input[''minId'']：运行期从 input 对象读取（与 ''1'' 同一入参）
#
# 【必须输出】print JSON 数组，键=输出属性 code（此处无输出目标概念，仅记录 JSON）

# ''1'' 占位符替换后内联
min_id = ''1''

ID_KEY = ''prop_mte737eq6byt''   # 标识
AGE_KEY = ''11''                 # 年龄

rows = input.get(''source'', {}).get(''rows'') or []

def normalize(p):
    return {
        ID_KEY: p.get(ID_KEY),
        AGE_KEY: p.get(AGE_KEY),
    }

threshold = input[''minId''] if ''minId'' in input else min_id

result = []
seen = set()
for p in rows:
    if p.get(ID_KEY) is None:
        continue
    if int(p[ID_KEY]) < threshold:
        continue
    if p[ID_KEY] in seen:
        continue
    seen.add(p[ID_KEY])
    result.append(normalize(p))

result.sort(key=lambda r: r[ID_KEY])

print(json.dumps(result, ensure_ascii=False))
