# ===== 字段映射入参函数 =====
# 脚本不写死任何属性code，全部通过入参名动态获取：
#   - pkField   ：主键字段（映射到数据来源概念的属性，如 标识 prop_mte737eq6byt）
#   - dataField ：要处理的数据字段（映射到数据来源概念的属性，如 年龄 11）
# 执行时 input.source.rows 每行键=属性code；
# input[pkField]/input[dataField] = 动作绑定时映射到的属性 code。
# 脚本用这两个 code 从每行动态取字段，实现"同一函数复用不同概念/字段"。
#
# 【必须输出】print JSON 数组（键=输出属性 code），可 UPSERT 写回；无输出目标概念时仅记录 JSON。

pk = input[''pkField'']
field = input[''dataField'']

rows = input.get(''source'', {}).get(''rows'') or []

result = []
seen = set()
for p in rows:
    if p.get(pk) is None:
        continue
    if p[pk] in seen:
        continue
    seen.add(p[pk])
    result.append({
        pk: p.get(pk),
        field: p.get(field),
    })

result.sort(key=lambda r: (r.get(pk) is not None, r.get(pk)))

print(json.dumps(result, ensure_ascii=False))
