const payload = JSON.parse(event.payload_json || ''{}'');
const orderItems = Array.isArray(payload.items) ? payload.items : [];

// 模拟关联查询：获取订单中各产品信息、BOM、物料库存、产线产能
const products = input.relations.product || [];
const productMaterials = input.relations.product_material || [];
const materials = input.relations.material || [];
const materialInventories = input.relations.material_inventory || [];
const productionLines = input.relations.production_line || [];
const capacitySlots = input.relations.production_capacity_slot || [];

const result = [];

for (const item of orderItems) {
  const productId = item.product_id;
  const qty = parseInt(item.quantity) || 1;
  
  const product = products.find(p => p.id === productId);
  if (!product) continue;
  
  // 获取BOM
  const bomItems = productMaterials.filter(pm => pm.product_id === productId);
  
  // 检查关键物料库存可用性（取首个仓库可用量）
  let materialCheck = [];
  for (const bomItem of bomItems) {
    const material = materials.find(m => m.id === bomItem.material_id);
    const inventory = materialInventories.find(inv => inv.material_id === bomItem.material_id);
    const available = inventory?.available_quantity || 0;
    const required = qty * bomItem.quantity_per_unit * (1 + (bomItem.scrap_rate || 0));
    materialCheck.push({
      material_code: material?.material_code,
      required_quantity: required,
      available_quantity: available,
      sufficient: available >= required
    });
  }
  
  // 粗略排产窗口：取最早空闲产能槽位（模拟）
  let earliestSlot = null;
  if (capacitySlots.length > 0) {
    const sortedSlots = [...capacitySlots].sort((a, b) => new Date(a.start_time) - new Date(b.start_time));
    earliestSlot = sortedSlots[0];
  }
  
  result.push({
    order_id: orderId,
    product_code: product.product_code,
    product_name: product.product_name,
    order_quantity: qty,
    standard_minutes: product.standard_minutes,
    min_batch_qty: product.min_batch_qty,
    material_availability_check: materialCheck,
    suggested_start_time: earliestSlot?.start_time || null,
    suggested_production_line: earliestSlot?.production_line_id || null,
    status: ''PREVIEW''
  });
}

console.log(JSON.stringify(result));', '基于新到达的 sales_order 事件，结合产品BOM、物料库存、产线产能等数据，生成排产建议预览（不保存、不执行）', true, true, 1, '超级管理员', '2026-09-28T17:02:30.088000'::timestamp, 1, '超级管理员', '2026-09-28T17:02:30.088000'::timestamp, 0, '[]', 2100851215264628737, NULL, NULL, 5000, 1);

# ===== 字段映射入参函数 =====
# 脚本不写死任何属性code，全部通过入参名动态获取：
#   - pkField   ：主键字段（映射到数据来源概念的属性，如 标识 prop_mte737eq6byt）
#   - dataField ：要处理的数据字段（映射到数据来源概念的属性，如 年龄 11）
# 执行时 input.source.rows 每行键=属性code；
# input[pkField]/input[dataField] = 动作绑定时映射到的属性 code。
# 脚本用这两个 code 从每行动态取字段，实现"同一函数复用不同概念/字段"。
#
# 【必须输出】print JSON 数组（键=输出属性 code），可 UPSERT 写回；无输出目标概念时仅记录 JSON。

pk = input[''pkField'']
field = input[''dataField'']

rows = input.get(''source'', {}).get(''rows'') or []

result = []
seen = set()
for p in rows:
    if p.get(pk) is None:
        continue
    if p[pk] in seen:
        continue
    seen.add(p[pk])
    result.append({
        pk: p.get(pk),
        field: p.get(field),
    })

result.sort(key=lambda r: (r.get(pk) is not None, r.get(pk)))

print(json.dumps(result, ensure_ascii=False))
', '字段映射入参函数：pkField/dataField 两个入参在动作绑定时映射到数据来源概念属性，脚本按映射动态取字段、按主键去重并按主键升序输出，仅记录输出 JSON', true, true, NULL, 'admin', '2026-08-31T15:50:56.771952'::timestamp, NULL, NULL, '2026-08-31T15:50:56.771952'::timestamp, 0, '["pkField","dataField"]', NULL, NULL, NULL, 5000, 1);

# ===== 人物概念：属性 code 即行键 =====
#   标识 = prop_mte737eq6byt （映射物理列 id）
#   年龄 = 11               （映射物理列 age）
# input.source.rows = [ {"prop_mte737eq6byt":1,"11":30}, ... ]
#
# 【入参引用】minId：执行时手填，通过 input[''minId''] 读取（数字或数字字符串均可）
# 【必须输出】print JSON 数组（键=输出属性 code），可 UPSERT 写回/仅记录

ID_KEY = ''prop_mte737eq6byt''   # 标识
AGE_KEY = ''11''                 # 年龄

rows = input.get(''source'', {}).get(''rows'') or []

# minId 可能是数字或数字字符串，统一转 int；未填则不按 id 过滤
threshold = None
if ''minId'' in input and input[''minId''] is not None and str(input[''minId'']).strip() != '''':
    try:
        threshold = int(input[''minId''])
    except (ValueError, TypeError):
        threshold = None

def normalize(p):
    return {ID_KEY: p.get(ID_KEY), AGE_KEY: p.get(AGE_KEY)}

result = []
seen = set()
for p in rows:
    v = p.get(ID_KEY)
    if v is None or v == '''':
        continue
    try:
        v_int = int(v)
    except (ValueError, TypeError):
        continue
    if threshold is not None and v_int < threshold:
        continue
    if v_int in seen:
        continue
    seen.add(v_int)
    result.append(normalize(p))

result.sort(key=lambda r: str(r.get(ID_KEY)))

print(json.dumps(result, ensure_ascii=False))
', '人物概念数据清洗：按标识(prop_mte737eq6byt)过滤 id(需>=${minId})、去重并按标识升序输出标识与年龄(11)；读取 input.source.rows，无输出目标概念，仅记录输出 JSON', true, true, NULL, 'admin', '2026-08-31T15:19:35.318564'::timestamp, NULL, NULL, '2026-08-31T15:19:35.318564'::timestamp, 0, '["minId"]', NULL, NULL, NULL, 5000, 1);
const product = input.source.rows.find(r => r.id === product_id);
if (!product) throw new Error(`Product not found: ${product_id}`);

const bomItems = input.relations.productcontainsmaterial.filter(r => r.product_id === product_id);
const materialIds = bomItems.map(b => b.material_id);

const materials = input.source.rows.filter(r => materialIds.includes(r.id));
const inventories = input.relations.materialhasinventory || [];

let totalATP = Number.MAX_SAFE_INTEGER;

for (const bomItem of bomItems) {
  const material = materials.find(m => m.id === bomItem.material_id);
  if (!material) continue;

  const inv = inventories.find(i => i.material_id === material.id);
  const available = inv ? (inv.available_quantity - inv.reserved_quantity + inv.inbound_quantity) : 0;
  const requiredPerUnit = bomItem.quantity_per_unit * (1 + (bomItem.scrap_rate || 0));
  const requiredForOneProduct = requiredPerUnit;
  
  const materialATP = requiredForOneProduct > 0 ? Math.floor(available / requiredForOneProduct) : Number.MAX_SAFE_INTEGER;
  totalATP = Math.min(totalATP, materialATP);
}

totalATP = isNaN(totalATP) || !isFinite(totalATP) ? 0 : totalATP;

const result = [{
  id: `atp_${Date.now()}_${product_id}_${customer_id}_${as_of_date}`,
  space_code: product.space_code,
  product_id: product_id,
  customer_id: customer_id,
  as_of_date: as_of_date,
  atp_quantity: totalATP,
  calculation_timestamp: new Date().toISOString()
}];
console.log(JSON.stringify(result));', '基于指定客户、产品和日期，计算该客户对该产品的可承诺量（ATP），综合考虑当前可用库存、在途物料、BOM展开后的物料需求及安全库存约束。', true, true, 1, '超级管理员', '2026-09-24T19:46:09.129000'::timestamp, 1, '超级管理员', '2026-09-24T19:46:09.129000'::timestamp, 0, '["product_id","customer_id","as_of_date"]', 2100851217407918084, NULL, 2100851215264628737, 5000, 1);

